using System.ComponentModel.DataAnnotations;
namespace NMB_HLabSys.ViewModels;
public sealed class TechnicianIdentityViewModel { public string Name { get; set; } = "Technician"; public string EmployeeNumber { get; set; } = ""; }
public sealed class TechnicianDashboardViewModel { public TechnicianIdentityViewModel Technician { get; set; } = new(); public int PendingSamples { get; set; } public int InProgress { get; set; } public int Completed { get; set; } public int AwaitingVerification { get; set; } public int WaitingToBeSelected { get; set; } public int WaitingToBeReviewed { get; set; } public int Urgent { get; set; } public int Overdue { get; set; } public int NearingDue { get; set; } public TechnicianDashboardFilterViewModel Filter { get; set; } = new(); public List<string> Categories { get; set; } = new(); public List<TechnicianChartItemViewModel> CategoryChart { get; set; } = new(); public List<TechnicianChartItemViewModel> WorkloadChart { get; set; } = new(); public List<TechnicianWorkItemViewModel> WorkItems { get; set; } = new(); }
public sealed class TechnicianChartItemViewModel { public string Label { get; set; } = ""; public int Value { get; set; } public string? Category { get; set; } public string? Status { get; set; } public string? Due { get; set; } public string? Urgency { get; set; } }
public sealed class TechnicianProfileViewModel { [Required,StringLength(100)] public string Name { get; set; } = ""; [Required,StringLength(100)] public string Surname { get; set; } = ""; [Required,EmailAddress,StringLength(255)] public string Email { get; set; } = ""; [Phone,StringLength(20)] public string ContactNumber { get; set; } = ""; public string EmployeeNumber { get; set; } = ""; public string Specialization { get; set; } = ""; public string Qualification { get; set; } = ""; public int YearsOfExperience { get; set; } }
public sealed class TechnicianDashboardFilterViewModel { public string? Status { get; set; } public string? Urgency { get; set; } public string? Category { get; set; } public string? Due { get; set; } public string? RequestNumber { get; set; } }
public sealed class TechnicianWorkItemViewModel { public int RequestTestId { get; set; } public string RequestNumber { get; set; } = ""; public string Patient { get; set; } = ""; public string TestName { get; set; } = ""; public string Category { get; set; } = ""; public string Urgency { get; set; } = ""; public string Status { get; set; } = ""; public DateTime? StartedAt { get; set; } public DateTime? DueAt { get; set; } public bool IsOverdue { get; set; } public string ClinicalNotes { get; set; } = ""; public string Conditions { get; set; } = ""; public string Allergies { get; set; } = ""; public string Medications { get; set; } = ""; public string ReviewNotes { get; set; } = ""; }
public sealed class ReceiveSamplesViewModel { public TechnicianIdentityViewModel Technician { get; set; } = new(); public List<SampleQueueItemViewModel> Samples { get; set; } = new(); }
public sealed class SampleQueueItemViewModel { public int SampleId { get; set; } public string RequestNumber { get; set; } = ""; public string Patient { get; set; } = ""; public string Barcode { get; set; } = ""; public string SampleType { get; set; } = ""; public string Status { get; set; } = ""; public DateTime RequestedAt { get; set; } }
public sealed class PerformTestsViewModel { public TechnicianIdentityViewModel Technician { get; set; } = new(); public List<TechnicianWorkItemViewModel> Tests { get; set; } = new(); }
public sealed class CaptureResultViewModel { [Required] public int RequestTestId { get; set; } [Required] public string ResultValue { get; set; } = ""; public decimal? NumericValue { get; set; } [StringLength(1000)] public string? Notes { get; set; } }
public sealed class VerificationQueueViewModel { public TechnicianIdentityViewModel Technician { get; set; } = new(); public List<VerificationItemViewModel> Results { get; set; } = new(); }
public sealed class VerificationItemViewModel { public int ResultId { get; set; } public int RequestTestId { get; set; } public string RequestNumber { get; set; } = ""; public string TestName { get; set; } = ""; public string PerformedBy { get; set; } = ""; public string ResultValue { get; set; } = ""; public bool IsAbnormal { get; set; } public string Status { get; set; } = ""; }
public sealed class VerifyResultViewModel { [Required] public int ResultId { get; set; } [StringLength(1000)] public string? ReviewNotes { get; set; } }
public sealed class TechnicianCompletedTestsReportViewModel { [Required, DataType(DataType.Date)] public DateTime StartDate { get; set; } = DateTime.Today.AddDays(-30); [Required, DataType(DataType.Date)] public DateTime EndDate { get; set; } = DateTime.Today; }
public sealed class TechnicianReportDataViewModel { public TechnicianIdentityViewModel Technician { get; set; } = new(); public DateTime StartDate { get; set; } public DateTime EndDate { get; set; } public List<TechnicianReportCategoryViewModel> Categories { get; set; } = new(); public int TotalCompleted { get; set; } public int StatCount { get; set; } public int OverdueCompleted { get; set; } }
public sealed class TechnicianReportCategoryViewModel { public string Category { get; set; } = "Uncategorised"; public List<TechnicianReportTestViewModel> Tests { get; set; } = new(); }
public sealed class TechnicianReportTestViewModel { public string RequestNumber { get; set; } = ""; public string TestName { get; set; } = ""; public string Urgency { get; set; } = ""; public DateTime CompletedAt { get; set; } public bool IsAbnormal { get; set; } public bool IsOverdue { get; set; } }


